import React from 'react';
import { useLocation, useNavigate } from 'react-router-dom';
import { setAudience } from '../utils/audience';

export default function AudienceGate(){
  const navigate = useNavigate();
  const { state } = useLocation();
  const backTo = state?.from?.pathname || '/';

  const choose = (aud) => {
    setAudience(aud);                 // 'RESIDENT' | 'TOURIST'
    navigate(backTo, { replace: true });
  };

  return (
    <div className="aud-wrap">
      <img src="/logo.png" alt="Conecta Pinamar" className="aud-logo" />
      <div className="aud-panels">
        <button className="aud-half left"  onClick={()=>choose('RESIDENT')}>
          SOY RESIDENTE
        </button>
        <button className="aud-half right" onClick={()=>choose('TOURIST')}>
          SOY TURISTA
        </button>
      </div>

      <style>{`
        .aud-wrap{
          position:fixed; inset:0; background:#F7D34A; display:flex;
          flex-direction:column; align-items:center; justify-content:center;
        }
        .aud-logo{ height:64px; margin-bottom:24px; }
        .aud-panels{ display:grid; grid-template-columns:1fr 1fr; width:min(980px, 92vw); height:min(520px, 70vh); border-radius:18px; overflow:hidden; }
        .aud-half{ border:0; margin:0; font-weight:900; font-size:clamp(18px, 3.5vw, 28px); letter-spacing:.5px; cursor:pointer; transition:transform .15s ease, box-shadow .15s ease, background .15s ease; }
        .aud-half.left{ background:rgba(255,255,255,.3); }
        .aud-half.right{ background:rgba(0,0,0,.05); }
        .aud-half:hover{ transform:scale(1.02); box-shadow:0 12px 32px rgba(0,0,0,.18); }
        .aud-half:active{ transform:scale(1.00); box-shadow:none; }
      `}</style>
    </div>
  );
}
